-- Rebuild Medina Book 3 lesson 5 strictly from the supplied Arabic sharh.
-- The sharh combines lessons 4 and 5 under one heading; اسم المفعول and ما العاملة عمل ليس belong to lesson 5.
-- Canonical page references: Sharkh_Medinskiy_3.pdf, PDF pages 29-31.
-- Two DOC control-character Qur'anic runs were transcribed literally from the visible PDF scan.

begin;
do $migration$
declare old_rule_count integer; new_rule_count integer; source_count integer;
begin
  select count(*) into old_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '5';
  if old_rule_count <> 2 then raise exception 'Expected 2 generated Book 3 lesson 5 rules, found %', old_rule_count; end if;
  delete from public.rule_sections where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '5');
  delete from public.rule_sources where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '5');
  delete from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '5';
  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar) values
('Мединский курс (Том 3)', '5', 'اسْمُ الْمَفْعُولِ (страдательное причастие, имя объекта действия)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-nasb">اسْمُ الْمَفْعُولِ</span> يُصَاغُ مِنَ الْفِعْلِ الْمَبْنِيِّ لِلْمَجْهُولِ لِلدَّلَالَةِ عَلَى مَا وَقَعَ عَلَيْهِ الْفِعْلُ.</span><p class="rule-study-text">Это производное имя обозначает то, на что направлено действие.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Образование от простого трёхбуквенного глагола</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفِعْلُ الْمَبْنِيُّ لِلْمَجْهُولِ</span><span class="rule-table-ru">пассивный глагол</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُهُ</span><span class="rule-table-ru">тип глагола</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-table-ru">страдательное причастие</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَصْلُهُ وَتَغْيِيرُهُ</span><span class="rule-table-ru">исходная форма и изменение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">عُلِمَ</span><span class="rule-table-ru">было узнано</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صَحِيحٌ سَالِمٌ</span><span class="rule-table-ru">правильный без хамзы и удвоения</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَعْلُومٌ</span><span class="rule-table-ru">известный</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">—</span><span class="rule-table-ru">—</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أُكِلَ</span><span class="rule-table-ru">было съедено</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صَحِيحٌ مَهْمُوزٌ</span><span class="rule-table-ru">правильный с хамзой</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَأْكُولٌ</span><span class="rule-table-ru">съеденный</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">—</span><span class="rule-table-ru">—</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سُئِلَ</span><span class="rule-table-ru">его спросили</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صَحِيحٌ مَهْمُوزٌ</span><span class="rule-table-ru">правильный с хамзой</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَسْؤُولٌ</span><span class="rule-table-ru">тот, кого спросили</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">—</span><span class="rule-table-ru">—</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">قُرِئَ</span><span class="rule-table-ru">было прочитано</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صَحِيحٌ مَهْمُوزٌ</span><span class="rule-table-ru">правильный с хамзой</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَقْرُوءٌ</span><span class="rule-table-ru">прочитанный</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">—</span><span class="rule-table-ru">—</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سُرَّ</span><span class="rule-table-ru">его обрадовали</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صَحِيحٌ مُضَعَّفٌ</span><span class="rule-table-ru">правильный удвоенный</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَسْرُورٌ</span><span class="rule-table-ru">обрадованный; радостный</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">—</span><span class="rule-table-ru">—</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وُقِفَ</span><span class="rule-table-ru">было остановлено</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلٌّ مِثَالٌ</span><span class="rule-table-ru">слабый первый</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَوْقُوفٌ</span><span class="rule-table-ru">остановленный</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">—</span><span class="rule-table-ru">—</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">قِيلَ</span><span class="rule-table-ru">было сказано</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلٌّ أَجْوَفُ وَاوِيٌّ</span><span class="rule-table-ru">слабый средний с вау</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَقُولٌ</span><span class="rule-table-ru">сказанный</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَقْوُولٌ؛ نُقِلَتْ حَرَكَةُ الْوَاوِ، وَهِيَ الضَّمَّةُ، إِلَى الْقَافِ، فَالْتَقَى سَاكِنَانِ فِي مَقُوْوْلٍ، فَحُذِفَتْ إِحْدَى الْوَاوَيْنِ.</span><span class="rule-table-ru">В исходной форме مَقْوُولٌ дамма вау перенесена на каф; после встречи двух безогласовочных букв в مَقُوْوْلٍ одна вау удалена.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بِيعَ</span><span class="rule-table-ru">было продано</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلٌّ أَجْوَفُ يَائِيٌّ</span><span class="rule-table-ru">слабый средний с йа</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَبِيعٌ</span><span class="rule-table-ru">проданный</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَبْيُوعٌ؛ نُقِلَتْ حَرَكَةُ الْيَاءِ، وَهِيَ الضَّمَّةُ، إِلَى الْبَاءِ، فَالْتَقَى سَاكِنَانِ فِي مَبُيْوْعٍ، فَحُذِفَتْ وَاوُ الْمَفْعُولِ، وَقُلِبَتْ ضَمَّةُ الْبَاءِ كَسْرَةً.</span><span class="rule-table-ru">В исходной форме مَبْيُوعٌ дамма йа перенесена на ба; после встречи двух безогласовочных букв удалена вау модели, а дамма ба заменена касрой.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">دُعِيَ</span><span class="rule-table-ru">его призвали</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلٌّ نَاقِصٌ وَاوِيٌّ</span><span class="rule-table-ru">конечно-слабый с вау</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَدْعُوٌّ</span><span class="rule-table-ru">призванный</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَدْعُوْوٌ؛ أُدْغِمَتِ الْوَاوُ فِي الْأُخْرَى.</span><span class="rule-table-ru">В исходной форме مَدْعُوْوٌ одна вау слита с другой.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">هُدِيَ</span><span class="rule-table-ru">его наставили</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلٌّ نَاقِصٌ يَائِيٌّ</span><span class="rule-table-ru">конечно-слабый с йа</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَهْدِيٌّ</span><span class="rule-table-ru">наставленный</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَهْدُوْيٌ؛ اجْتَمَعَتِ الْوَاوُ وَالْيَاءُ، وَكَانَتِ الْأُولَى سَاكِنَةً، فَقُلِبَتِ الْوَاوُ يَاءً، وَكُسِرَ مَا قَبْلَهَا، ثُمَّ أُدْغِمَتِ الْيَاءُ فِي الْأُخْرَى.</span><span class="rule-table-ru">В исходной форме مَهْدُوْيٌ встретились вау и йа, первая была без огласовки; вау превратилась в йа, предыдущая буква получила касру, затем две йа слились.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وُقِيَ</span><span class="rule-table-ru">его защитили</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلٌّ لَفِيفٌ مَفْرُوقٌ</span><span class="rule-table-ru">двойной слабый разделённый</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَوْقِيٌّ</span><span class="rule-table-ru">защищённый</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَوْقُوْيٌ؛ نَفْسُ التَّغْيِيرَاتِ فِي هُدِيَ.</span><span class="rule-table-ru">В исходной форме مَوْقُوْيٌ происходят те же изменения, что в форме от هُدِيَ.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">طُوِيَ</span><span class="rule-table-ru">его сложили</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلٌّ لَفِيفٌ مَقْرُونٌ</span><span class="rule-table-ru">двойной слабый смежный</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَطْوِيٌّ</span><span class="rule-table-ru">сложенный</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَطْوُوْيٌ؛ نَفْسُ التَّغْيِيرَاتِ فِي هُدِيَ.</span><span class="rule-table-ru">В исходной форме مَطْوُوْيٌ происходят те же изменения, что в форме от هُدِيَ.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">يُصَاغُ اسْمُ الْمَفْعُولِ مِنَ الثُّلَاثِيِّ الْمَزِيدِ وَغَيْرِ الثُّلَاثِيِّ عَلَى لَفْظِ الْمُضَارِعِ، مَعَ قَلْبِ حَرْفِ الْمُضَارَعَةِ مِيمًا مَضْمُومَةً وَفَتْحِ مَا قَبْلَ الْآخِرِ.</span><p class="rule-study-text">Берётся форма настояще-будущего пассивного глагола: его начальная буква заменяется мимом с даммой, а предпоследняя буква получает фатху.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры от трёхбуквенных с добавочными буквами и от нетрёхбуквенных глаголов</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَاضِي الْمَجْهُولُ</span><span class="rule-table-ru">прошедший пассивный глагол</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُضَارِعُ الْمَجْهُولُ</span><span class="rule-table-ru">настояще-будущий пассивный глагол</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-table-ru">страдательное причастие</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">عُلِّمَ</span><span class="rule-table-ru">его обучили</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُعَلَّمُ</span><span class="rule-table-ru">его обучают</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مُعَلَّمٌ</span><span class="rule-table-ru">обученный</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">نُودِيَ</span><span class="rule-table-ru">его позвали</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُنَادَى</span><span class="rule-table-ru">его зовут</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مُنَادًى</span><span class="rule-table-ru">тот, кого позвали</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اُسْتُغْفِرَ</span><span class="rule-table-ru">у него попросили прощения</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُسْتَغْفَرُ</span><span class="rule-table-ru">у него просят прощения</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مُسْتَغْفَرٌ</span><span class="rule-table-ru">тот, у кого просят прощения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بُعْثِرَ</span><span class="rule-table-ru">его разбросали</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُبَعْثَرُ</span><span class="rule-table-ru">его разбрасывают</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مُبَعْثَرٌ</span><span class="rule-table-ru">разбросанный</span></td></tr></tbody></table></div></div></div>', 1, 'rule', 'Страдательное причастие обозначает объект действия; шарх показывает его образование от простых трёхбуквенных и остальных глаголов со всеми слабыми преобразованиями.', 'اسْمُ الْمَفْعُولِ اسْمٌ يُصَاغُ مِنَ الْفِعْلِ الْمَبْنِيِّ لِلْمَجْهُولِ لِلدَّلَالَةِ عَلَى مَا وَقَعَ عَلَيْهِ الْفِعْلُ. يُصَاغُ مِنَ الثُّلَاثِيِّ الْمُجَرَّدِ عَلَى وَزْنِ مَفْعُولٍ، وَمِنَ الثُّلَاثِيِّ الْمَزِيدِ وَغَيْرِ الثُّلَاثِيِّ عَلَى لَفْظِ الْمُضَارِعِ مَعَ قَلْبِ حَرْفِ الْمُضَارَعَةِ مِيمًا مَضْمُومَةً وَفَتْحِ مَا قَبْلَ الْآخِرِ.'),
('Мединский курс (Том 3)', '5', 'مَا الْعَامِلَةُ عَمَلَ لَيْسَ (частица مَا, работающая как لَيْسَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-particle">مَا الْحِجَازِيَّةُ</span> حَرْفُ نَفْيٍ نَاسِخٌ يَرْفَعُ الاِسْمَ وَيَنْصِبُ الْخَبَرَ.</span><p class="rule-study-text">Она входит в именное предложение и работает как <span class="ar-inline ar-tone-particle" dir="rtl" lang="ar">لَيْسَ</span>: её имя стоит в именительном состоянии, а сказуемое — в винительном.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Почему она называется хиджазской</span><p class="rule-study-text"><span class="ar-inline ar-tone-particle" dir="rtl" lang="ar">تُسَمَّى مَا الْحِجَازِيَّةَ؛ لِأَنَّهَا تَعْمَلُ عَمَلَ لَيْسَ فِي لُغَتِهِمْ.</span></p><p class="rule-study-text">Она называется хиджазской مَا, потому что в речи жителей Хиджаза выполняет управление لَيْسَ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры без добавочной ба</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">﴿ مَا هَذَا بَشَرًا ﴾</span><span class="rule-example-ru">«Это не человек».</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">مَا أَنْتَ مُجْتَهِدًا.</span><span class="rule-example-ru">Ты не усерден.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">قَدْ يَقْتَرِنُ خَبَرُ مَا الْحِجَازِيَّةِ بِالْبَاءِ الزَّائِدَةِ.</span><p class="rule-study-text">К сказуемому хиджазской مَا может присоединяться добавочная ба.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры с добавочной ба</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">﴿ وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ ﴾</span><span class="rule-example-ru">«Аллах не остаётся в неведении о том, что вы совершаете».</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">مَا خَالِدٌ بِمَرِيضٍ.</span><span class="rule-example-ru">Халид не болен.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">مَا أَنَا بِقَارِئٍ.</span><span class="rule-example-ru">Я не читающий.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب без добавочной ба</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">грамматический разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْحُ</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَا</span><span class="rule-table-ru">не</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ نَفْيٍ نَاسِخٌ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">изменяющая отрицательная частица, построенная на сукуне, без синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">تَعْمَلُ عَمَلَ لَيْسَ</span><span class="rule-table-ru">управляет как لَيْسَ</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَنَا</span><span class="rule-table-ru">я</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">ضَمِيرُ رَفْعٍ مُنْفَصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ اسْمُ مَا الْحِجَازِيَّةِ.</span><span class="rule-table-ru">отдельное местоимение именительного состояния, построенное на сукуне; занимает позицию имени хиджазской مَا</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ مَا الْحِجَازِيَّةِ</span><span class="rule-table-ru">имя хиджазской مَا</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">تَاجِرًا</span><span class="rule-table-ru">торговец</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">خَبَرُ مَا الْحِجَازِيَّةِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">сказуемое хиджазской مَا в винительном состоянии; признак — явная фатха</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرُ مَا الْحِجَازِيَّةِ</span><span class="rule-table-ru">сказуемое хиджазской مَا</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Предложение без добавочной ба</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">مَا أَنَا تَاجِرًا.</span><span class="rule-example-ru">Я не торговец.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب с добавочной ба</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">грамматический разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْحُ</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَا</span><span class="rule-table-ru">не</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ نَفْيٍ نَاسِخٌ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">изменяющая отрицательная частица, построенная на сукуне, без синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">تَعْمَلُ عَمَلَ لَيْسَ</span><span class="rule-table-ru">управляет как لَيْسَ</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَنَا</span><span class="rule-table-ru">я</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">ضَمِيرُ رَفْعٍ مُنْفَصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ اسْمُ مَا الْحِجَازِيَّةِ.</span><span class="rule-table-ru">отдельное местоимение именительного состояния, построенное на сукуне; занимает позицию имени хиджазской مَا</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ مَا الْحِجَازِيَّةِ</span><span class="rule-table-ru">имя хиджазской مَا</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْبَاءُ</span><span class="rule-table-ru">ба</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ جَرٍّ زَائِدٌ مَبْنِيٌّ عَلَى الْكَسْرِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">добавочный предлог, построенный на касре, без синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ جَرٍّ زَائِدٌ</span><span class="rule-table-ru">добавочный предлог</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">تَاجِرٍ</span><span class="rule-table-ru">торговец</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">خَبَرُ مَا الْحِجَازِيَّةِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الْمُقَدَّرَةُ، مَنَعَ مِنْ ظُهُورِهَا اشْتِغَالُ الْمَحَلِّ بِحَرَكَةِ حَرْفِ الْجَرِّ الزَّائِدِ، وَهِيَ الْكَسْرَةُ.</span><span class="rule-table-ru">сказуемое хиджазской مَا в винительном состоянии; фатха подразумевается, потому что место занято касрой добавочного предлога</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَنْصُوبٌ مَحَلًّا</span><span class="rule-table-ru">занимает позицию винительного состояния</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Предложение с добавочной ба</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">مَا أَنَا بِتَاجِرٍ.</span><span class="rule-example-ru">Я не торговец.</span></div></div></div></div>', 2, 'rule', 'Хиджазская مَا отрицает именное предложение и управляет как لَيْسَ; её сказуемое может присоединять добавочную ба.', 'مَا الْعَامِلَةُ عَمَلَ لَيْسَ حَرْفُ نَفْيٍ نَاسِخٌ يَدْخُلُ عَلَى الْجُمْلَةِ الاِسْمِيَّةِ فَيَرْفَعُ الاِسْمَ وَيَنْصِبُ الْخَبَرَ، وَتُسَمَّى مَا الْحِجَازِيَّةَ. وَقَدْ يَقْتَرِنُ خَبَرُهَا بِالْبَاءِ الزَّائِدَةِ، فَيَبْقَى مَنْصُوبًا مَحَلًّا، وَتُقَدَّرُ فَتْحَتُهُ لِاشْتِغَالِ الْمَحَلِّ بِكَسْرَةِ الْبَاءِ.');
insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'اسمُ الْمَفْعُولِ
اسمُ المفعولِ ، هو : اسم يُصَاغُ من الفعلِ المبنيِّ للمجهولِ للدَّلالةِ على ما وقعَ عليه الفعلُ.
صِيَاغَتُهُ : اسم المفعول مُشْتَقٌّ من الفعلِ ، ويُصَاغُ على وزن ( مَفْعُول ) من الفعل الثُّلاثِيَّ
المجرَّدِ ، نحو : مَكْتُوب ، مأْخُوذ ، مَأْتِي ، مَعْدُودٌ ، مَرْئِي .
* جدولٌ يُبَيَّنُ صِياغةَ اسمِ المفعولِ من الأفعالِ الثُّلاثيَّةِ المجرَّدةِ .
الفعل
نوعه
اسم المفعول
أصله
عُلِمَ
صحيح سالم
مَعْلُومٌ
---------
أُكِلَ
صحيح مهموز
مَأْكُولٌ
---------
سُئِلَ
صحيح مهموز
مَسْؤُولٌ
---------
قُرِئَ
صحيح مهموز
مَقْرُوءٌ
---------
سُرَّ
صحيح مُضَعَّف
مَسْرُورٌ
---------
وُقِفَ
معتلّ مِثَال
مَوْقُوفٌ
---------
قِيلَ
معتلّ أجوف واويّ
مَقُولٌ
مَقْوُوْلٌ . نُقِلَتْ حركة الواو ( الضمة ) إلى حرف القَاف فالتقى ساكنان ( مَقُوْوْل ) فحُذِفَتْ إِحدى الواوين .
بِيعَ
معتلّ أجوف يائيّ
مَبِيعٌ
مَبْيُوْعٌ . نُقِلت حركة الياء ( الضمة ) إلى حرف الباء فالتقى ساكنان ( مَبُيْوْعٌ ) فحُذِفت واو المفعول ، وقُلِبت ضمة الباء كسرة .
دُعِيَ
معتلّ ناقص واويّ
مَدْعُوٌّ
مَدْعُوْوٌ . أُدْغِمَت الواو في الأخرى .
هُدِيَ
معتلّ ناقص يائيّ
مَهْدِيٌّ
مَهْدُوْيٌ . اجْتَمَعَت الواو والياء ، وكانت الأولى ساكنة فَقُلِبَت الواو ياءً ، وكُسِرَ ما قبلها ، ثم أُدغمت الياء في الأخرى .
وُقِي
معتلّ لفيف مَفْرُوق
مَوْقِيٌّ
مَوْقُوْيٌ . نفس التغييرات في ( هُدِيَ ) .
طُوِيَ
معتل لفيف مَقْرُون
مَطْوِيٌّ
مَطْوُوْيٌ . نفس التغييرات في ( هُدِيَ ) .
* إذا كان الفعلُ ثلاثياً مزيداً ، أو غيرَ ثلاثيٍّ صِيغَ اسمُ المفعولِ منه كما يلي :
يُصَاغ على لفظ المضارع مع قَلْبِ حرف المضارع ميما مضمومة ، وفتح ما قبل الآخِر ،
نحو : عُلّمَ        يُعَلَّم : مُعَلَّمٌ .                          نُودِيَ         يُنَادَى : مُنَادًى .
اُسْتُغْفِرَ        يُسْتَغْفَرُ : مُسْتَغْفَرٌ .                  بُعْثِرَ           يُبَعْثَرُ : مُبَعْثَرٌ .', 29, 30, 1 from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '5' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'مَا الْعَامِلَةُ عَمَلَ لَيْسَ
ما العاملةُ عَمَلَ ليسَ : حرف نَفْي تدخل على الجملة الاسميّة فترفعُ الاسم ، وتنصب الخبر. وتُسَمَّى ما الحِجَازِيَّةَ ؛ لأنها تعملُ عملَ ( ليسَ ) في لُغَتِهِمْ .
الأمثلة :
قال تعالى : ﴿ مَا هَذَا بَشَراً ﴾ ونحو : ما أنت مجتهداً .
* قد يقترن خبرها بالباء الزَّائدة ، نحو قوله تعالى : ﴿ وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ ﴾ .
ونحو : ما خالدٌ بمريضٍ ، وما أنا بِقَارِئ .
الإعراب : ما أنا تاجراً . ما أنا بتاجرٍ .
ما : حرف نَفْي نَاسِخ مبني على السكون لا محلّ له من الإعراب .
أنا : ضمير رفع منفصل مبني على السكون في محل رفع اسم ما الحجازيّة .
تاجراً : خبر ما الحجازيَّة منصوب وعلامة نصبه الفتحة الظاهرة .
بتاجر : الباء حرف جر زائد مبني على الكسر لا محلّ له من الإعراب .
تاجرٍ  : خبر ما الحجازية منصوب وعلامة نصبه الفتحة المقدَّرة منع من
ظهورها اشتغال المحلَّ بحركة حرف الجر الزائد ( الكسرة ) .', 30, 31, 1 from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '5' and sort_order = 2;
  select count(*) into new_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '5';
  select count(*) into source_count from public.rule_sources rs join public.rules r on r.id = rs.rule_id where r.course_name = 'Мединский курс (Том 3)' and r.lesson_number = '5';
  if new_rule_count <> 2 or source_count <> 2 then raise exception 'Book 3 lesson 5 verification failed: rules %, sources %', new_rule_count, source_count; end if;
end
$migration$;
commit;
